"""The catalog: catalog/<slice>.yaml (human-edited) or, off-server, dist/catalog.json (generated by `garage build`).

  load(repo=None) -> {"topics": [topic...], "resources": {rid: resource}, "synonyms": {word: [words]}}
      topic    = the YAML topic + "slice"; its "resources" list keeps every entry as written, each with "rid" added
      resource = the richest entry for that rid (most filled fields, then longest note; gaps filled from the others)
                 + "rid", "topics" (every topic id listing it), "slice" (of the first listing);
                 from dist/catalog.json also "pin" and "trust" as they were at build time
  normalize_url(u) -> rid   lowercase scheme+host, no trailing "/", no ".git", no "#fragment" (query kept); GitHub
                            /tree|blob/<ref>/<path> -> /tree/HEAD/<path> (40-hex sha refs kept)
  is_runnable(res)          use in {skill, mcp, plugin, template, vendor} or kind in {skill, mcp, plugin, template, snippet}
  github_repo(url)          -> ("owner/name", "sub/path") for github.com URLs (path from /tree|blob/<ref>/...), else None

A resource that is one folder of a bigger GitHub repo has its own URL .../tree/<ref>/<path> (and `path`), so every
skill or plugin inside anthropics/skills or trailofbits/skills is its own rid with its own pin and trust record.
"""
import json
import re
from pathlib import Path
from urllib.parse import unquote, urlsplit

from . import paths

RUNNABLE_USE = {"skill", "mcp", "plugin", "template", "vendor"}
RUNNABLE_KIND = {"skill", "mcp", "plugin", "template", "snippet"}
SKIP_FILES = {"synonyms.yaml"}
PERMISSIVE = {"MIT", "MIT-0", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC", "0BSD", "Unlicense", "CC0-1.0",
              "Zlib", "BSL-1.0", "PostgreSQL", "MPL-2.0", "Apache-2.0 WITH LLVM-exception", "MIT OR Apache-2.0",
              "NCSA", "CC-BY-4.0", "W3C-20150513", "OFL-1.1", "Python-2.0", "BlueOak-1.0.0"}

PACKAGED = Path(__file__).resolve().parent / "_dist" / "catalog.json"   # in the wheel (uvx/pip installs)

_cache = {}


SHA40 = re.compile(r"^[0-9a-fA-F]{40}$")
GH_REF = re.compile(r"^(/[^/]+/[^/]+)/(?:tree|blob)/([^/]+)(/.*)?$")


def normalize_url(u):
    """The rid. GitHub .../tree|blob/<ref>/<path> becomes .../tree/HEAD/<path> (main, master, HEAD and blob links to
    one folder are one resource); an explicit 40-hex commit ref is kept, a bare /tree/<ref> is the repository."""
    s = urlsplit(str(u).strip())
    path = s.path.rstrip("/")
    if path.endswith(".git"):
        path = path[:-4].rstrip("/")
    host = s.netloc.lower()
    if host in ("github.com", "www.github.com"):
        host = "github.com"
        m = GH_REF.match(path)
        if m:
            base, ref, rest = m.group(1), m.group(2), m.group(3) or ""
            if SHA40.match(ref):
                path = f"{base}/tree/{ref.lower()}{rest}"
            else:
                path = f"{base}/tree/HEAD{rest}" if rest else base
    out = f"{s.scheme.lower()}://{host}{path}"
    return out + (f"?{s.query}" if s.query else "")


def is_runnable(res):
    return res.get("use") in RUNNABLE_USE or res.get("kind") in RUNNABLE_KIND


def is_permissive(lic):
    """SPDX id or expression: OR = any side permissive, AND = every part permissive; LicenseRef-* never."""
    lic = str(lic or "").strip()
    if lic in PERMISSIVE:
        return True
    if " OR " in lic:
        return any(is_permissive(x) for x in lic.split(" OR "))
    if " AND " in lic:
        return all(is_permissive(x) for x in lic.split(" AND "))
    return False


def github_repo(url):
    s = urlsplit(str(url))
    if s.netloc.lower() not in ("github.com", "www.github.com"):
        return None
    parts = [unquote(p) for p in s.path.split("/") if p]
    if len(parts) < 2:
        return None
    repo = f"{parts[0]}/{parts[1].removesuffix('.git')}"
    sub = "/".join(parts[4:]) if len(parts) > 4 and parts[2] in ("tree", "blob") else ""
    return repo, sub


def _str(v):
    return v.isoformat() if hasattr(v, "isoformat") else v


def _yaml_files(repo):
    d = Path(repo) / "catalog"
    return sorted(p for p in d.glob("*.yaml") if p.name not in SKIP_FILES)


def dist_file(repo=None):
    """The generated catalog with pins and trust records: <repo>/dist/catalog.json, else (no catalog in the repo at
    all: pip/uvx installs off-server) the copy bundled in the package. None when neither applies."""
    repo = Path(repo) if repo else paths.repo()
    dist = repo / "dist" / "catalog.json"
    if dist.is_file():
        return dist
    if not _yaml_files(repo) and PACKAGED.is_file():
        return PACKAGED
    return None


def sources(repo=None):
    """The files load() reads (for freshness checks): the catalog YAMLs + synonyms, or dist/catalog.json."""
    repo = Path(repo) if repo else paths.repo()
    files = _yaml_files(repo)
    if files:
        syn = repo / "catalog" / "synonyms.yaml"
        return files + ([syn] if syn.is_file() else [])
    dist = dist_file(repo)
    return [dist] if dist else []


def load_yaml(path):
    import yaml
    loader = getattr(yaml, "CSafeLoader", yaml.SafeLoader)   # libyaml: 10x faster on the 1.7 MB catalog
    with open(path, encoding="utf-8") as f:
        return yaml.load(f, Loader=loader) or {}


def richness(r):
    """How much an entry says: filled fields first, then the length of its note (duplicate rids keep the richer)."""
    filled = sum(1 for k, v in r.items() if k not in ("rid", "topics", "slice") and v not in (None, "", [], {}))
    return filled, len(str(r.get("note") or ""))


def merge(docs, synonyms=None):
    """[slice doc, ...] -> the load() shape. Docs are the parsed YAML files (slice, generated, topics)."""
    topics, resources, gen = [], {}, ""
    for doc in docs:
        sl = doc.get("slice") or ""
        gen = max(gen, str(_str(doc.get("generated") or "")))
        for t in doc.get("topics") or []:
            t = dict(t)
            t["slice"] = sl
            rs = []
            for r in t.get("resources") or []:
                r = {k: _str(v) for k, v in r.items()}
                r["rid"] = rid = normalize_url(r.get("url", ""))
                rs.append(r)
                if rid in resources:
                    old = resources[rid]
                    if t["id"] not in old["topics"]:
                        old["topics"].append(t["id"])
                    rich, poor = (r, old) if richness(r) > richness(old) else (old, r)
                    both = {k: v for k, v in poor.items() if k not in ("topics", "slice")}
                    both.update({k: v for k, v in rich.items() if k not in ("topics", "slice")
                                 and v not in (None, "", [], {})})
                    resources[rid] = dict(both, topics=old["topics"], slice=old["slice"])
                else:
                    resources[rid] = dict(r, topics=[t["id"]], slice=sl)
            t["resources"] = rs
            topics.append(t)
    return {"topics": topics, "resources": resources, "synonyms": synonyms or {}, "generated": gen}


def load(repo=None):
    repo = Path(repo) if repo else paths.repo()
    files = sources(repo)
    key = (str(repo), tuple((str(p), p.stat().st_mtime_ns) for p in files))
    if key in _cache:
        return _cache[key]
    yamls = _yaml_files(repo)
    if yamls:
        syn = repo / "catalog" / "synonyms.yaml"
        synonyms = (load_yaml(syn) or {}).get("synonyms", {}) if syn.is_file() else {}
        out = merge([load_yaml(p) for p in yamls], synonyms)
    elif files:
        with open(files[0], encoding="utf-8") as f:
            out = json.load(f)
        out.setdefault("synonyms", {})
    else:
        raise FileNotFoundError(f"no catalog in {repo} (catalog/*.yaml or dist/catalog.json); set GARAGE_REPO")
    _cache.clear()
    _cache[key] = out
    return out


_by_id = {}


def topics_by_id(cat):
    """{topic id: topic} for a loaded catalog (cached per catalog object)."""
    key = id(cat)
    if key not in _by_id or _by_id[key][0] is not cat:
        _by_id.clear()
        _by_id[key] = (cat, {t["id"]: t for t in cat["topics"]})
    return _by_id[key][1]


def topic(cat, tid):
    for t in cat["topics"]:
        if t["id"] == tid:
            return t
    return None


ID_RE = re.compile(r"^[a-z0-9]+(\.[a-z0-9][a-z0-9-]*){2,}$")


def health():
    try:
        cat = load()
    except Exception as e:   # noqa: BLE001 - doctor reports, never raises
        return [("FAIL", f"catalog: {e}")]
    return [("PASS", f"catalog {len(cat['topics'])} topics, {len(cat['resources'])} resources from {paths.repo()}")]
